sys_script_include.script:
var PatientUtils = Class.create();
PatientUtils.prototype = {
    initialize: function(patientId) {
        this.source = new GlideRecord('u_patient_record');
        this.id = patientId;
    },

    fetchAllPatientDetailsByPatientID: function() {
        this.source.get(this.id);
        results = {
            patient_number: this.source.getValue('u_number'),
            patient_user_id: this.source.getValue('u_user_patient'),
            patient_first_name: this.source.getValue('u_first_name'),
            patient_last_name: this.source.getValue('u_last_name'),
            patient_dob: this.source.getValue('u_dob').toString(),
            patient_gender: this.source.getValue('u_gender'),
            patient_status: this.source.getValue('u_status'),
            patient_vip: this.source.getValue('u_vip'),
            patient_contact_number: this.source.getValue('u_contact_number'),
            patient_email: this.source.getValue('u_email'),
            patient_address: this.source.getValue('u_address'),
            patient_emergency_contact_number: this.source.getValue('u_emergency_contact_number'),

        };
        return results;
    },

    checkIfVIP: function() {
        this.source.get(this.id);
        if (this.source.u_vip) {
            return true;
        } else {
            return false;
        }
    },


    getAge: function() {
        this.source.get(this.id);
        var today = new GlideDateTime(gs.nowDateTime());
        var dateOfBirth = new GlideDateTime(this.source.u_dob);
        var age = Math.round(GlideDateTime.subtract(dateOfBirth, today).getNumericValue() / (1000 * 60 * 60 * 24 * 365));
        return age;
    },

	fetchPatientAppointment : function(){
		var appointmentGr = new GlideRecord('u_appointments');
		appointmentGr.addQuery('u_patient_id', this.id);
		appointmentGr.query();
		return appointmentGr;
	},

	fetchPatientMedications : function(){
		var medGr = new GlideRecord('u_medication');
		medGr.addQuery('u_patient_i(d', this.id);
		medGr.query();
		return medGr;
	},

	fetchPatientLabTests : function(){
		var labGr = new GlideRecord('u_lab_test');
		labGr.addQuery('u_patient_id', this.id);
		labGr.query();
		return labGr;
	},

	fetchPatientBills : function(){
		var billGr = new GlideRecord('u_billing');
		billGr.addQuery('u_patient_id', this.id);
		billGr.query();
		return billGr;
	},

	fetchPatientInsurances : function(){
		var insGr = new GlideRecord('u_insurance');
		insGr.addQuery('u_patient_id', this.id);
		insGr.query();
		return insGr;
	},



    type: 'PatientUtils'
};
